	}
	if len(rangeStartArgs) != len(rangeEndArgs) {
		return "", nil, fmt.Errorf("mismatched number of start and end args: %d != %d", len(rangeStartArgs), len(rangeEndArgs))
	}
	explodedArgs := make([]any, 0, len(b.argsMapping))
